mapper.select:
SELECT * FROM sys_operation_log
WHERE 1 = 1

    AND username LIKE CONCAT('%', #{q.username}, '%')


    AND module = #{q.module}


    AND status = #{q.status}


    AND create_time >= #{q.startDate}


    AND create_time < DATE_ADD(#{q.endDate}, INTERVAL 1 DAY)

ORDER BY create_time DESC, id DESC
